import sys,math
sys.path.insert(0,'/home/claude/work/suprabhatam')
from sdata1 import talk,svg,person,F,SUN,HILL,B
from sdata2 import lab,crowd
D=dict
END=lambda n: ['madhurādhipater','akhilaṃ madhuram ‖%d‖'%n]
def K(x=110,y=0,s=1):
    return f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2.5"><circle cy="56" r="15" fill="#3b6fd0"/><path d="M-10 40 q10 -14 20 0" fill="#111"/><path d="M4 36 q10 -20 6 -30" stroke="#2a9d6f" stroke-width="3" fill="none"/><circle cx="10" cy="8" r="4" fill="#1d6fb8" stroke="#2a9d6f"/><path d="M-22 150 q-4 -66 22 -78 q26 12 22 78z" fill="#ffd60a"/><path d="M-14 82 q14 30 28 0" fill="none" stroke="#e05a8a" stroke-width="4"/></g>'
FLUTE=lambda x,y,r=-14: f'<path d="M{x} {y} l50 {r}" stroke="#7a5a3a" stroke-width="5" stroke-linecap="round"/>'
RIVER='<path d="M0 130 q55 -12 110 0 t110 0 V160 H0z" fill="#4aa3df" stroke="#111" stroke-width="2"/>'
COW=lambda x,y,s=1: f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2"><ellipse rx="22" ry="12" fill="#fff"/><circle cx="-24" cy="-6" r="8" fill="#fff"/><path d="M-14 10 v12 M14 10 v12 M-6 10 v12 M6 10 v12"/><circle cx="4" cy="-2" r="4" fill="#8a6a4a"/></g>'
V=[
D(n='1',lines=[['adharaṃ madhuraṃ','vadanaṃ madhuraṃ'],['nayanaṃ madhuraṃ','hasitaṃ madhuram |'],['hṛdayaṃ madhuraṃ','gamanaṃ madhuraṃ'],END(1)],theme='HIS FACE, HIS SMILE, HIS HEART',
 svg=svg('Young Krishna smiling, with a peacock feather, walking gracefully, with hearts and honey drops around him',K(110)+''.join(f'<text x="{x}" y="{y}" {F} font-size="14" fill="#e05a8a">♥</text>' for x,y in [(40,50),(170,60),(50,110),(176,120)])+lab(110,20,'MADHURAM!',13),B),
 mean='His lips are sweet, His face is sweet, His eyes are sweet, His smile is sweet; His heart is sweet, His walk is sweet. Everything about the Lord of Sweetness is sweet.',
 plain='Sweet lips, sweet face, sweet eyes, sweet smile, sweet heart, sweet walk: everything about Kṛṣṇa is sweet.',
 words=[('adharam','<b>lips</b>'),('vadanam','<b>face</b>'),('nayanam','<b>eyes</b>'),('hasitam','<b>smile</b>'),('hṛdayam · gamanam','<b>heart</b> · <b>walk</b>'),('madhura-adhipati','<b>Lord of sweetness</b>')],
 deep='<p><b>Beginning with the face.</b> The poet looks at Kṛṣṇa as a lover looks: lips first, then face, eyes, smile. Then he goes inward, to the heart, and back out, to the way He walks.</p><p><b>The refrain.</b> Every verse ends <i>madhurādhipater akhilaṃ madhuram</i>: "everything about the Lord of Sweetness is sweet". Each verse lists six sweet things and then gives up: it is all sweet.</p><p><b>A pun.</b> <i>Madhurā</i> is also an old name of Mathurā, Kṛṣṇa\'s birthplace; so <i>madhurādhipati</i> can be read as "Lord of Mathurā" too.</p>',
 cards=('💡 Mādhurya','Sweetness: the loving, intimate side of the Lord, as against His majesty (aiśvarya).','💡 Mathurā','Kṛṣṇa\'s birthplace on the Yamunā, also called Madhurā or Madhupurī.'),
 inner='When you truly love someone, you stop listing reasons. Everything about them is dear.',
 talk=('The same word, over and over?','That\'s the magic! "Madhuram, madhuram": like a child who can only say "sweet!" because there\'s no better word.'),
 key='"Adharaṃ madhuram": <b>everything about Kṛṣṇa is sweet</b>.'),
D(n='2',lines=[['vacanaṃ madhuraṃ','caritaṃ madhuraṃ'],['vasanaṃ madhuraṃ','valitaṃ madhuram |'],['calitaṃ madhuraṃ','bhramitaṃ madhuraṃ'],END(2)],theme='HIS WORDS, HIS WAYS, HIS WANDERINGS',
 svg=svg('Krishna in yellow silk talking and laughing, then wandering through a forest of trees',K(80,0,.9)+''.join(f'<g transform="translate({140+30*k} {130-10*(k%2)})"><path d="M0 0 v-30" stroke="#7a5a3a" stroke-width="4"/><circle cy="-40" r="16" fill="#2a9d6f" stroke="#111" stroke-width="2"/></g>' for k in range(3))+'<path d="M40 40 q-20 -10 -8 -24 q30 -4 30 16z" fill="#fff" stroke="#111"/>'+lab(110,20,'VṚNDĀVANA',11),B),
 mean='His words are sweet, His deeds are sweet, His garments are sweet, His posture is sweet; His movements are sweet, His wanderings are sweet. Everything about the Lord of Sweetness is sweet.',
 plain='What He says, what He does, what He wears, how He stands, how He moves, where He roams: all sweet.',
 words=[('vacanam','<b>words</b>'),('caritam','<b>deeds</b>, story'),('vasanam','<b>clothes</b>: the yellow silk'),('valitam','<b>posture</b>, the bend of His body'),('calitam','<b>movement</b>'),('bhramitam','<b>wandering</b>')],
 deep='<p><b>From face to life.</b> Verse 1 was about how He looks; verse 2 is about how He lives: what He says, does and wears, and where He goes.</p><p><b>Valita.</b> "The bend": Kṛṣṇa is often shown in the <i>tribhaṅga</i> pose, bent at neck, waist and knee, playing His flute.</p><p><b>Pītāmbara.</b> His garment is the yellow silk (<i>pītāmbara</i>), one of His names. Even His clothes are sweet because He wears them (compare Veṅkaṭeśa Maṅgalāśāsanam verse 11).</p>',
 cards=('💡 Tribhaṅga','The graceful three-bend pose of Kṛṣṇa playing the flute.','💡 Pītāmbara','"Yellow-clad": Kṛṣṇa\'s silk garment, and a name for Him.'),
 inner='Love sees sweetness in ordinary things: how someone speaks, stands, walks.',
 talk=('His clothes are sweet too?','Everything is! What He says, what He wears, even how He wanders about Vṛndāvana.'),
 key='Words, deeds, clothes, wanderings: <b>all sweet</b>.'),
D(n='3',lines=[['veṇur madhuro','reṇur madhuraḥ'],['pāṇir madhuraḥ','pādau madhurau |'],['nṛtyaṃ madhuraṃ','sakhyaṃ madhuraṃ'],END(3)],theme='HIS FLUTE, THE DUST OF HIS FEET',
 svg=svg('Krishna dancing and playing the flute, dust rising from his feet, with friends around',K(110,0,.9)+FLUTE(116,62)+''.join(f'<circle cx="{90+8*k}" cy="{150-(k%3)*4}" r="2" fill="#c9a26b"/>' for k in range(6))+person(40,150,'#ff8c1a','#f2c79b',.55)+person(180,150,'#2a9d6f','#f2c79b',.55)+''.join(f'<text x="{x}" y="{y}" {F} font-size="16" fill="#1d6fb8">♪</text>' for x,y in [(170,40),(190,70)]),B),
 mean='His flute is sweet, the dust of His feet is sweet, His hands are sweet, His feet are sweet; His dance is sweet, His friendship is sweet. Everything about the Lord of Sweetness is sweet.',
 plain='His flute, the dust His feet raise, His hands, His feet, His dancing, His friendship: all sweet.',
 words=[('veṇuḥ','<b>flute</b>'),('reṇuḥ','<b>dust</b> (of His feet)'),('pāṇiḥ','<b>hand</b>'),('pādau','<b>two feet</b>'),('nṛtyam','<b>dance</b>'),('sakhyam','<b>friendship</b>')],
 deep='<p><b>The flute.</b> Kṛṣṇa\'s flute (<i>veṇu</i>, <i>muralī</i>) called the cows, the gopīs and all Vṛndāvana. In the Bhāgavatam, even rivers stopped to listen.</p><p><b>The dust.</b> Devotees long for the dust of His feet (<i>pāda-reṇu</i>), or of His devotees\' feet. Vraja\'s dust is still held sacred.</p><p><b>Friendship.</b> <i>Sakhya</i>, friendship with God, is one of the moods of bhakti: the cowherd boys loved Him as their friend, wrestling and eating with Him.</p>',
 cards=('💡 Muralī','Kṛṣṇa\'s bamboo flute; Muralīdhara, "flute-bearer", is His name.','💡 Sakhya-bhāva','Loving God as a friend: the mood of the cowherd boys and Arjuna.'),
 inner='Even the dust of His path is sacred. Walk where He walked.',
 talk=('Even the dust is sweet?','The dust from His dancing feet! Devotees still treasure the dust of Vraja.'),
 key='Flute, dust, dance, friendship: <b>all sweet</b>.'),
D(n='4',lines=[['gītaṃ madhuraṃ','pītaṃ madhuraṃ'],['bhuktaṃ madhuraṃ','suptaṃ madhuram |'],['rūpaṃ madhuraṃ','tilakaṃ madhuraṃ'],END(4)],theme='SINGING, EATING, SLEEPING',
 svg=svg('Little Krishna eating butter from a pot with a tilak on his forehead, then asleep, with a song note above',K(70,0,.8)+'<path d="M110 120 q-4 -30 20 -34 q24 4 20 34z" fill="#c0703a" stroke="#111" stroke-width="2"/><path d="M116 90 q14 -10 28 0" fill="#fff" stroke="#111"/>'+lab(130,140,'NAVANĪTA',8)+'<path d="M70 38 v-8" stroke="#e63946" stroke-width="4"/>'+f'<text x="180" y="50" {F} font-size="16">💤</text>',B),
 mean='His singing is sweet, His drinking is sweet, His eating is sweet, His sleeping is sweet; His form is sweet, His tilaka is sweet. Everything about the Lord of Sweetness is sweet.',
 plain='How He sings, drinks, eats and sleeps; His beautiful form and the mark on His forehead: all sweet.',
 words=[('gītam','<b>song</b>'),('pītam','<b>drinking</b>'),('bhuktam','<b>eating</b>'),('suptam','<b>sleeping</b>'),('rūpam','<b>form</b>'),('tilakam','the <b>tilaka</b> mark')],
 deep='<p><b>Everyday life.</b> Singing, drinking, eating, sleeping: the most ordinary acts. In Kṛṣṇa they are lovely because they are His. This is the heart of <i>mādhurya</i> bhakti: God as a beloved child or friend, not a distant king.</p><p><b>The butter thief.</b> Kṛṣṇa\'s eating means, above all, the stolen butter of Gokula: the favourite childhood story.</p><p><b>Puṣṭimārga sevā.</b> In Vallabha\'s tradition, the Lord is served through the day like a beloved child: woken, fed, dressed, put to rest.</p>',
 cards=('💡 Tilaka','A sacred mark on the forehead; Vaiṣṇavas wear the ūrdhva-puṇḍra.','💡 Navanīta-cora','"Butter thief": Kṛṣṇa as the mischievous child of Gokula.'),
 inner='God is found in ordinary moments, not only in temples.',
 talk=('Even His sleeping is sweet?','Think of a sleeping child! In Vallabha\'s path, the Lord is cared for like a child: fed, sung to, put to sleep.'),
 key='Even eating and sleeping: <b>sweet, because it is He</b>.'),
D(n='5',lines=[['karaṇaṃ madhuraṃ','taraṇaṃ madhuraṃ'],['haraṇaṃ madhuraṃ','ramaṇaṃ madhuram |'],['vamitaṃ madhuraṃ','śamitaṃ madhuraṃ'],END(5)],theme='HIS DEEDS, HIS RESCUE, HIS MISCHIEF',
 svg=svg('Krishna carrying friends across a river, and running off with a pot of butter',RIVER+K(80,0,.75)+person(130,124,'#ff8c1a','#f2c79b',.45)+'<path d="M160 100 q-4 -24 16 -28 q20 4 16 28z" fill="#c0703a" stroke="#111" stroke-width="2"/>'+lab(176,120,'HARAṆA!',8),B),
 mean='His actions are sweet, His saving is sweet, His stealing is sweet, His love-play is sweet; what He gives away is sweet, His calm is sweet. Everything about the Lord of Sweetness is sweet.',
 plain='What He does, how He rescues, how He steals hearts and butter, how He plays, what He gives, how He calms: all sweet.',
 words=[('karaṇam','<b>doing</b>, deeds'),('taraṇam','<b>carrying across</b>, saving'),('haraṇam','<b>stealing</b>'),('ramaṇam','<b>sporting</b>, love-play'),('vamitam','<b>giving out</b>'),('śamitam','<b>calming</b>, peace')],
 deep='<p><b>A harder verse.</b> These words have several meanings, and commentators differ. <i>Taraṇa</i>: carrying across, as He carries devotees across saṃsāra. <i>Haraṇa</i>: stealing: butter, clothes, and hearts. <i>Ramaṇa</i>: His play, His love.</p><p><b>Vamita and śamita.</b> Read variously: <i>vamita</i> as what He "lets out", such as the prasāda of chewed betel He shares, or His giving; <i>śamita</i> as His peace, or His calming of devotees\' troubles.</p><p><b>Even mischief.</b> Stealing is wrong; but His stealing of hearts is sweet. Love sees everything differently.</p>',
 cards=('💡 Hari','"The one who takes away": His name, from the same root as haraṇa.','💡 Variant','Some texts read smaraṇam, "remembering", for ramaṇam.'),
 inner='Let Him steal your heart. That theft makes you richer.',
 talk=('Stealing is sweet?','When He steals hearts, yes! Hari literally means "the one who takes away", our sorrows and our hearts.'),
 key='Rescuing, stealing, playing: <b>His every act is sweet</b>.',
 note='Interpretations of vamitam and śamitam vary between commentators.'),
D(n='6',lines=[['guñjā madhurā','mālā madhurā'],['yamunā madhurā','vīcī madhurā |'],['salilaṃ madhuraṃ','kamalaṃ madhuraṃ'],END(6)],theme='HIS GARLAND, HIS RIVER',
 svg=svg('A garland of red and black gunja berries, the Yamuna river with waves and lotuses',RIVER+''.join(f'<path d="M{x} 136 q-10 -16 0 -22 q10 6 0 22z" fill="#f08aa6" stroke="#111"/>' for x in (40,110,180))+''.join(f'<circle cx="{110+60*math.cos(k*0.35+0.3)}" cy="{30+60*math.sin(k*0.35+0.3)}" r="4" fill="#e63946" stroke="#111"/>' for k in range(9))+lab(110,154,'YAMUNĀ',10),B),
 mean='His guñjā-berry necklace is sweet, His garland is sweet; the Yamunā is sweet, her waves are sweet; her water is sweet, her lotuses are sweet. Everything about the Lord of Sweetness is sweet.',
 plain='His berry necklace and garland, the river Yamunā, its waves, its water, its lotuses: all sweet.',
 words=[('guñjā','<b>guñjā berries</b> (red and black seeds)'),('mālā','<b>garland</b>'),('yamunā','the <b>river Yamunā</b>'),('vīcī','<b>waves</b>'),('salilam','<b>water</b>'),('kamalam','<b>lotus</b>')],
 deep='<p><b>Beyond His body.</b> The sweetness now spreads outward: to what He wears, and then to His river. Things become sweet by being near Him.</p><p><b>Guñjā.</b> A cowherd boy\'s necklace of bright red-and-black seeds: simple jewellery for a village Lord.</p><p><b>The Yamunā.</b> The river of Vṛndāvana, where Kṛṣṇa played, bathed, subdued Kāliya and danced the rāsa. In Vallabha\'s tradition the Yamunā is honoured as a goddess; he wrote the <i>Yamunāṣṭakam</i> to her.</p>',
 cards=('💡 Guñjā-mālā','A necklace of guñjā seeds, worn by Kṛṣṇa as a cowherd.','💡 Yamunāṣṭakam','Vallabha\'s eight verses in praise of the Yamunā.'),
 inner='Whatever is close to Him becomes sweet. Stay close.',
 talk=('Now the river is sweet too?','Anything near Him becomes sweet: His necklace, His garland, the Yamunā, even her lotuses!'),
 key='Garland, river, waves, lotuses: <b>sweet by being near Him</b>.'),
D(n='7',lines=[['gopī madhurā','līlā madhurā'],['yuktaṃ madhuraṃ','muktaṃ madhuram |'],['dṛṣṭaṃ madhuraṃ','śiṣṭaṃ madhuraṃ'],END(7)],theme='THE GOPĪS AND HIS PLAY',
 svg=svg('Krishna with gopis in a circle dance under the moon',
  '<circle cx="190" cy="26" r="12" fill="#fff8c0" stroke="#111"/>'+''.join(person(110+74*math.cos(k*1.047),118+22*math.sin(k*1.047),'#e05a8a','#f2c79b',.38) for k in range(6))+K(110,40,.5)+lab(40,26,'LĪLĀ',12),B),
 mean='The gopīs are sweet, His play is sweet; being with Him is sweet, being apart is sweet; His glance is sweet, His courtesy is sweet. Everything about the Lord of Sweetness is sweet.',
 plain='The gopīs and His games, being with Him and missing Him, His look and His manners: all sweet.',
 words=[('gopī','the <b>gopīs</b>, cowherd women'),('līlā','<b>divine play</b>'),('yuktam','<b>union</b>, being with Him'),('muktam','<b>release</b>, parting'),('dṛṣṭam','<b>His glance</b>'),('śiṣṭam','<b>courtesy</b>, His teaching')],
 deep='<p><b>The gopīs.</b> The cowherd women of Vraja, whose love for Kṛṣṇa is, for many traditions, the highest form of devotion: total, selfless, without calculation.</p><p><b>Even separation.</b> <i>Yuktaṃ … muktaṃ</i>: meeting Him is sweet, and so is parting. In the bhakti tradition, the longing of separation (<i>viraha</i>) is itself a deep form of love; the gopīs\' longing after Kṛṣṇa left Vraja is celebrated in song.</p><p><b>Līlā.</b> Everything He does is play: free, joyful, without need.</p>',
 cards=('💡 Viraha','The pain of separation from the beloved: a key mood of bhakti.','💡 Variant','Some texts read bhuktam ("eating") for muktam here.'),
 inner='Even missing Him is a way of loving Him.',
 talk=('Being apart is sweet?','Longing for Him keeps Him in your heart. The gopīs\' longing is one of the deepest forms of love.'),
 key='Union and separation: <b>both are sweet with Him</b>.'),
D(n='8',lines=[['gopā madhurā','gāvo madhurā'],['yaṣṭir madhurā','sṛṣṭir madhurā |'],['dalitaṃ madhuraṃ','phalitaṃ madhuraṃ'],END(8)],theme='HIS COWS, HIS STAFF, HIS WHOLE CREATION',
 svg=svg('Krishna with a herding staff among cows and cowherd boys on a green meadow under the sun',SUN(190,30,14)+'<rect x="0" y="120" width="220" height="40" fill="#7fc47f"/>'+K(110,0,.75)+'<path d="M134 60 v90" stroke="#7a5a3a" stroke-width="4"/>'+COW(40,130,.8)+COW(180,136,.7)+person(70,150,'#ff8c1a','#f2c79b',.4)+lab(60,26,'SṚṢṬI',11),B),
 mean='The cowherds are sweet, the cows are sweet, His staff is sweet, His creation is sweet; His crushing of evil is sweet, the fruit He gives is sweet. Everything about the Lord of Sweetness is sweet.',
 plain='His cowherd friends, His cows, His herding stick, the whole world He made, how He destroys evil, what He gives: all sweet.',
 words=[('gopāḥ','<b>cowherds</b>'),('gāvaḥ','<b>cows</b>'),('yaṣṭiḥ','<b>staff</b>, herding stick'),('sṛṣṭiḥ','<b>creation</b>'),('dalitam','<b>crushing</b>, trampling (evil)'),('phalitam','<b>fruit</b>, fulfilment')],
 deep='<p><b>From the cowshed to the cosmos.</b> The last verse moves from His friends, His cows and His stick to <i>sṛṣṭi</i>, the whole creation. The cowherd boy is the creator of the universe.</p><p><b>Dalita and phalita.</b> He crushes evil (as He crushed Kāliya and Kaṃsa) and brings everything to fruit. Destruction and fulfilment, both sweet in His hands.</p><p><b>The end of the list.</b> After 48 sweet things in 8 verses, the refrain says it all: <i>akhilaṃ madhuram</i>, everything is sweet.</p>',
 cards=('💡 Gopāla','"Protector of cows": the cowherd Kṛṣṇa.','💡 Govinda','"One who finds joy in cows", or "who is known through the Vedas".'),
 inner='If the creator is sweet, the creation is too. Look at the world with love.',
 talk=('The whole creation is sweet?','If He made it, it\'s His, and everything of His is sweet. That\'s where the hymn ends!'),
 key='From cows to the cosmos: <b>akhilaṃ madhuram, all is sweet</b>.'),
]
